mapper.select:
SELECT *
FROM reconciliation_snapshot
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND scenario_code=#{scenario}
AND cutoff_id=#{cutoffId}
AND scope_digest=#{digest} FOR UPDATE

SELECT *
FROM reconciliation_snapshot
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}

mapper.update:
UPDATE reconciliation_snapshot
SET state=#{state}, manifest_json=#{manifest}, completed_at=#{completedAt}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}
AND state='EXPORTING'

mapper.select:
SELECT part_no, row_count, sha256, payload
FROM snapshot_part
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND snapshot_id=#{snapshotId}
ORDER BY part_no

SELECT b.id, b.owner_id, b.sku_id, b.lot_id, b.on_hand_qty, k.base_unit
FROM stock_balance b JOIN sku k ON k.enterprise_id=b.enterprise_id
AND k.id=b.sku_id
WHERE b.enterprise_id=#{enterpriseId}
AND b.warehouse_id=#{warehouseId}
AND b.updated_at<#{cutoff}
ORDER BY b.id
LIMIT #{limit}
